{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/live_site.py",
      "detail": "The live-site dedup gate verifies hashes of supplied extracted text, but does not verify the raw page responses or reconstruct that text from them. HTTP status, final URL and retrieval time are also supplied fields. Thus a self-consistent but incorrect capture can support a DISTINCT verdict without establishing the actual live content.",
      "required_fix": "Archive and hash each raw response, bind its retrieval metadata, and reconstruct the reviewed text from those bytes. Hold the dedup gate when this evidence or adequate site coverage is missing; add a regression test for a self-consistent extracted-text mismatch."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/multilingual/startup.py; cloud_pilot/multilingual/__main__.py",
      "detail": "Startup checks out approved_main_sha after the entry point has loaded modules from the permitted code SHA, without explicitly requiring the two SHAs to match. With a differently bound approved plan, the process could run already-imported code from one commit while reading review inputs and later imports from another. The supplied plan currently uses the same SHA for both.",
      "required_fix": "Require code SHA and approved main SHA to match before checkout, or execute the complete reviewed runtime from an immutable worktree without switching its source tree. Test a valid permit with differing SHAs and assert failure before credential access."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
